import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 128,
        'dropout_rate': 0.1,
        'kernel_size': 8
    }

class AttentionPoolingCNN(nn.Module):
    """A 1D CNN with a learned attention-based pooling layer."""
    d_output: int
    task_type: str
    hidden_dim: int
    dropout_rate: float
    kernel_size: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        # 1. CNN Feature Extraction
        cnn_features = nn.Conv(
            features=self.hidden_dim,
            kernel_size=(self.kernel_size,)
        )(x)
        cnn_features = nn.relu(cnn_features)
        # cnn_features shape: (batch, seq_len, hidden_dim)

        # 2. Attention-based Pooling
        # Compute attention scores
        attention_scores = nn.Dense(features=1)(cnn_features) # (batch, seq_len, 1)
        # Normalize scores to get weights
        attention_weights = nn.softmax(attention_scores, axis=1) # (batch, seq_len, 1)

        # Compute weighted sum of features
        # (batch, seq_len, hidden_dim) * (batch, seq_len, 1) -> (batch, seq_len, hidden_dim)
        # Sum over the sequence length dimension
        weighted_features = jnp.sum(cnn_features * attention_weights, axis=1) # (batch, hidden_dim)

        # 3. Final prediction head
        x = nn.Dropout(rate=self.dropout_rate)(weighted_features, deterministic=deterministic)
        x = nn.Dense(self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class NetworkWrapper:
    def __init__(self, **kwargs):
        self.network = AttentionPoolingCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return NetworkWrapper(
        d_output=hparams["d_output"],
        task_type=hparams["task_type"],
        hidden_dim=hparams["hidden_dim"],
        dropout_rate=hparams["dropout_rate"],
        kernel_size=hparams["kernel_size"]
    )
